 const el=document.getElementById('yy-monitor-account');if(el){el.innerHTML=rows.map(a=>'<option value="'+yyEscape(a.id)+'">'+yyEscape(a.name)+'</option>').join('');if(!rows.some(a=>a.id===yyMonitorID))yyMonitorID=rows[0]?.id||'';el.value=yyMonitorID}
