var yyMonitorReadEpoch=0;
async function yyRefreshMonitor(){
 const id=yyMonitorID,epoch=++yyMonitorReadEpoch,scope=yyAccountControllerScope(),host=document.getElementById('yy-online-chart');
 const [r,status]=await Promise.all(['/api/youyuan/observations','/api/bot/status'].map(path=>yyRootAPI('GET',yyAccountPath(path,id))));
 if(id!==yyMonitorID||epoch!==yyMonitorReadEpoch||scope!==yyAccountControllerScope()||!host||document.getElementById('yy-online-chart')!==host)return;
 const row=yyAllAccountRows.find(a=>a.id===id);
 if(row&&status.ok!==false&&typeof status.connected==='boolean'){
  Object.assign(row,{connected:status.connected,connection_known:true,engine_ready:true,server:status.server||row.server});
  if(r.ok){row.online=r.online;row.online_source=r.source}
  yyRenderProjects();yyRenderAccountCards();
 }
 if(!r.ok){yyObservations=null;host.innerHTML='<div class="yy-empty">'+yyEscape(r.error||'账号记录暂时无法读取，连接状态未确认。')+'</div>';document.getElementById('yy-distribution-chart').innerHTML='';document.getElementById('yy-chat-table').innerHTML='';document.getElementById('yy-monitor-metrics').textContent=row?yyAccountStatusLabel(row):'状态待查询';return}
 yyObservations=r;document.getElementById('yy-online-source').textContent=r.source;
 document.getElementById('yy-monitor-metrics').innerHTML=yyBadge(row?yyAccountStatusLabel(row):'状态待查询',row?.connected===true)+yyBadge('当前观测 '+(r.online==null?'—':r.online))+yyBadge((r.chat||[]).length+' 条聊天记录');yyDrawOnline();yyDrawChat();
}
var yyChatPage=1,yyChatBucket=null,yyChatMonitorID='';
function yyChatFilterRows(rows,filters){
 const text=String(filters.text||'').trim().toLowerCase(),player=String(filters.player||''),start=filters.start?Date.parse(filters.start):NaN,end=filters.end?Date.parse(filters.end)+59999:NaN;
 return rows.filter(function(row){const time=Date.parse(row.time);return (!player||row.player===player)&&(!text||[row.player,row.message,row.server].join(' ').toLowerCase().includes(text))&&(!Number.isFinite(start)||time>=start)&&(!Number.isFinite(end)||time<=end)}).slice().sort((a,b)=>(Date.parse(b.time)||0)-(Date.parse(a.time)||0));
}
function yyChatGroupRows(rows,interval){
 const step=[900000,3600000,86400000].includes(Number(interval))?Number(interval):3600000,map=new Map();
 for(const row of rows){const time=Date.parse(row.time);if(!Number.isFinite(time))continue;const date=new Date(time),start=step===86400000?new Date(date.getFullYear(),date.getMonth(),date.getDate()).getTime():Math.floor(time/step)*step;map.set(start,(map.get(start)||0)+1)}
 return Array.from(map,([start,count])=>({start,end:step===86400000?new Date(new Date(start).getFullYear(),new Date(start).getMonth(),new Date(start).getDate()+1).getTime():start+step,count})).sort((a,b)=>a.start-b.start);
}
