 const value=id=>document.getElementById(id)?.value||'',base=yyChatFilterRows(all,{text:value('yy-chat-filter'),player:value('yy-chat-player'),start:value('yy-chat-start'),end:value('yy-chat-end')}),buckets=yyChatGroupRows(base,value('yy-chat-interval')),shown=buckets.slice(-48),peak=Math.max(1,...shown.map(b=>b.count)),bars=document.getElementById('yy-chat-bars');
