 host.innerHTML=rows.slice((yyChatPage-1)*size,yyChatPage*size).map(r=>'<article class="yy-chat-message"><header><strong>'+yyEscape(r.player||'未知玩家')+'</strong><time>'+yyEscape(new Date(r.time).toLocaleString('zh-CN'))+'</time></header>'+(r.server?'<small class="yy-chat-server">'+yyEscape(r.server)+'</small>':'')+'<p>'+yyEscape(r.message||'')+'</p></article>').join('')||'<p class="yy-empty">没有匹配的聊天记录</p>';
