function yyDrawOnline(){var rows=yyObservations.samples||[],valid=rows.filter(r=>r.online!=null);if(!valid.length){document.getElementById('yy-online-chart').innerHTML='<div class="yy-empty">尚未取得真实在线数据；连接后每 15 秒采样。</div>';document.getElementById('yy-distribution-chart').innerHTML='<div class="yy-empty">暂无人数分布数据</div>';return}var max=Math.max(1,...valid.map(r=>r.online)),begin=Date.parse(rows[0].time),end=Date.parse(rows[rows.length-1].time),span=Math.max(1,end-begin),path='',pen=false;rows.forEach(function(r){if(r.online==null){pen=false;return}path+=(pen?'L':'M')+(45+610*(Date.parse(r.time)-begin)/span).toFixed(1)+','+(175-150*r.online/max).toFixed(1)+' ';pen=true});var axes='<path d="M45 20V175H655" class="yy-chart-axis"/><text x="8" y="28">'+max+'</text><text x="22" y="175">0</text>';document.getElementById('yy-online-chart').innerHTML='<svg viewBox="0 0 700 215" role="img" aria-label="真实观测在线人数时间线">'+axes+'<path d="'+path+'" class="yy-chart-line"/><text x="45" y="203">'+yyEscape(new Date(begin).toLocaleTimeString('zh-CN'))+'</text><text x="595" y="203">'+yyEscape(new Date(end).toLocaleTimeString('zh-CN'))+'</text></svg>';var hours=Array.from({length:24},()=>({sum:0,n:0}));valid.forEach(r=>{var h=hours[new Date(r.time).getHours()];h.sum+=r.online;h.n++});var avg=hours.map(h=>h.n?h.sum/h.n:0),peak=Math.max(1,...avg);document.getElementById('yy-distribution-chart').innerHTML='<svg viewBox="0 0 700 210" role="img" aria-label="每小时在线人数观测均值">'+axes.replace('>'+max+'</text>','>'+peak.toFixed(1)+'</text>')+hours.map((h,i)=>'<rect x="'+(48+i*25)+'" y="'+(175-avg[i]*150/peak)+'" width="18" height="'+(avg[i]*150/peak)+'" class="yy-chart-bar"><title>'+i+' 时：'+(h.n?avg[i].toFixed(1)+' 人 / '+h.n+' 个样本':'无样本')+'</title></rect>'+ (i%3===0?'<text x="'+(48+i*25)+'" y="198">'+i+'时</text>':'')).join('')+'</svg>'}
