 if(a.id!=='main')actions.push(yyAccountActionHTML('yyEditAccount',[accountIndex],'令牌 / 服务器'),yyAccountActionHTML('yyToggleAccount',[accountIndex],a.enabled?'关闭连接':'启用连接'));
 else actions.push(yyAccountActionHTML('yyEnterAccount',['main','settings'],'配置主连接'),yyAccountActionHTML('yyToggleMainAccount',[],a.connection_known===false||a.connected==null?'管理连接':a.connected?'断开连接':'连接服务器'));
 actions.push(yyAccountActionHTML('yyEditAccountProfileRow',[index],'设备备注 / 分类'),yyAccountActionHTML('yyAccountTokenAction',[a.id,true],'复制令牌'),yyAccountActionHTML('yyObservationPage',[a.id],'观察方式'),yyAccountActionHTML('yyMonitorRow',[index],'查看记录'));
