async function yyPickAccountAvatar(){const file=this.files[0];if(!file)return;const out=document.getElementById('yy-profile-result');if(file.size>5*1024*1024||!['image/png','image/jpeg'].includes(file.type)){out.textContent='请选择5MB以内的PNG或JPEG图片。';return}const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=canvas.height=144;const ctx=canvas.getContext('2d');const size=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,144,144);yyEditingProfileAvatar=canvas.toDataURL('image/png');yyDrawProfilePreview(yyEditingProfileAvatar);out.textContent='头像已准备，保存资料后生效。';}catch{out.textContent='图片无法读取，请重新选择。'}finally{URL.revokeObjectURL(url)}}
