 delete subPageCache['机器人托管池'];openSubPage('机器人托管池',yyIntro('机器人托管池','管理员统一查看多台机器人；只在打开单个账号详情时查询实时状态。')+'<section class="card yy-admin-list-panel"><div class="yy-admin-toolbar"><label class="yy-search"><input id="yy-pool-search" aria-label="搜索托管机器人" placeholder="搜索账号、服务器或绑定玩家" oninput="yyPoolQuery=this.value;yyDrawPoolRows()"></label><select id="yy-pool-filter" aria-label="托管机器人分类" onchange="yyPoolFilter=this.value;yyDrawPoolRows()"><option value="all">全部账号</option><option value="enabled">已启用连接</option><option value="disabled">未启用连接</option><option value="bound">已绑定玩家</option><option value="idle">空闲 / 未绑定</option><option value="credential_missing">缺少令牌</option></select><button class="btn-s" onclick="yyPoolRefresh()">刷新列表</button></div><p id="yy-pool-feedback" class="yy-hint" role="status">正在读取托管池…</p><div id="yy-pool-list" class="yy-compact-list"></div></section>');
