function yyPoolDetail(index){
 if(!yyAccountAdmin()){T('需要管理员权限','e');return}const account=yyPoolRows[index];if(!account)return;yyPoolSelectedID=account.id;delete subPageCache['托管机器人详情'];delete _savedFormState['托管机器人详情'];
 const localIndex=yyAccountRows.findIndex(a=>a.id===account.id),buttons=yyAccountActionHTML('yyPoolDetailRefresh',[],'查询实时状态')+yyAccountActionHTML('yyAccountTokenAction',[account.id,true],'复制令牌')+(localIndex>=0?yyAccountActionHTML('yyEditAccount',[localIndex],'编辑账号配置'):'');
 openSubPage('托管机器人详情',yyIntro(account.name||account.id,'连接状态、服务器和玩家绑定分开管理。')+'<section class="card"><div class="yy-account-meta"><span>账号标识 <b>'+yyEscape(account.id)+'</b></span><span>账号凭据 <b>'+(account.has_token?'已保存，尚未验证本次进服':'缺少令牌')+'</b></span><span>自动重连 <b>'+(account.keep_alive?'已启用':'未启用')+'</b></span></div><p class="yy-hint" id="yy-pool-live" role="status">连接状态待查询</p><div class="yy-actions">'+buttons+'</div><label>目标服务器<input id="yy-pool-server" value="'+yyEscape(account.server||'')+'" placeholder="服务器号 / 房间号"></label><label>绑定玩家<input id="yy-pool-player" value="'+yyEscape(account.lease?.player||'')+'" placeholder="玩家游戏名"></label><p class="yy-hint">保存绑定不会自动传送；连接请求和观察策略分别执行。停止会取消此机器人的托管连接与绑定。</p><div class="yy-actions">'+['bind','start','release','stop'].map((action,i)=>yyAccountActionHTML('yyPoolDetailAction',[action],['保存绑定','连接此服务器','释放并等待 60 秒','停止机器人'][i],action==='start'?'btn':'btn-s')).join('')+'</div><p id="yy-pool-detail-result" role="status"></p></section>');
}
async function yyPoolDetailRefresh(){
 if(!yyAccountAdmin())return;const id=yyPoolSelectedID,scope=yyReadScope(),host=document.getElementById('yy-pool-live');if(!host||host.dataset.busy==='true')return;host.dataset.busy='true';host.textContent='正在查询该机器人…';
 try{const status=await yyPoolCall('status',[id]);if(id!==yyPoolSelectedID||scope!==yyReadScope()||document.getElementById('yy-pool-live')!==host)return;host.textContent=yyAccountStatusLabel(status)+' · '+(status.server||'未选择服务器')+' · 在线人数 '+(status.online==null?'未知':status.online)}catch(error){if(document.getElementById('yy-pool-live')===host)host.textContent=error.message}finally{host.dataset.busy='false'}
}
async function yyPoolDetailAction(action){
 if(!yyAccountAdmin()){T('需要管理员权限','e');return}const id=yyPoolSelectedID,scope=yyReadScope(),out=document.getElementById('yy-pool-detail-result');if(!out||out.dataset.busy==='true')return;
 const args=action==='release'?[id,{idle_seconds:60}]:action==='stop'?[id]:[id,{player:document.getElementById('yy-pool-player').value.trim(),server:document.getElementById('yy-pool-server').value.trim()}];out.dataset.busy='true';out.textContent='正在提交操作…';
 try{await yyPoolCall(action,args);if(scope!==yyReadScope()||document.getElementById('yy-pool-detail-result')!==out)return;out.textContent=action==='start'?'连接请求已提交，请查询实时状态确认结果':'操作已保存';T(out.textContent,'o');const row=yyPoolRows.find(a=>a.id===id);if(row){if(action==='bind')row.lease={phase:'bound',player:args[1].player};if(action==='release')row.lease={phase:'idle'};if(action==='stop'){row.enabled=false;row.lease=null}if(action==='start'){row.enabled=true;row.server=args[1].server||row.server}}}
 catch(error){if(document.getElementById('yy-pool-detail-result')===out)out.textContent=error.message;T(error.message,'e')}finally{out.dataset.busy='false'}
}
(window.__subPageRestoreHooks=window.__subPageRestoreHooks||[]).push({key:'机器人托管池',fn:function(){yyDrawPoolRows()}});
function yyRenderAuthPending(rows,batches){
 const host=document.getElementById('yy-ga-pending');if(!host)return;host.textContent='';
 for(const task of rows){const card=document.createElement('section');card.className='card';const title=document.createElement('h4'),status=document.createElement('p');title.textContent=(task.name||task.nickname||'游戏账号')+' · '+(task.verification_required?'待本人验证':'待重试登录');status.textContent=task.last_error||'继续原任务，不重复创建账号';status.setAttribute('role','status');card.append(title,status);if(task.verification_url){const b=document.createElement('button');b.className='btn-s';b.textContent='打开官方验证';b.onclick=()=>window.android&&android.openVerification?android.openVerification(task.verification_url):window.open(task.verification_url,'_blank','noopener');card.append(b)}let pwd,code;if(task.action==='login_4399'){pwd=document.createElement('input');pwd.type='password';pwd.placeholder='4399密码';pwd.autocomplete='off';card.append(pwd);if(task.captcha_url){const image=document.createElement('img');image.src=task.captcha_url;image.alt='4399验证码';code=document.createElement('input');code.placeholder='图片验证码';card.append(image,code)}}const next=document.createElement('button');next.className='btn';next.textContent='重试 / 验证完成后继续';next.onclick=async()=>{next.disabled=true;status.textContent='正在继续…';try{const r=await yyGameAuthAPI('POST',{action:task.action==='login_4399'?'resume_4399':'resume_guest',id:task.id,password:pwd?.value||'',captcha:code?.value||'',captcha_id:task.captcha_id||''});if(!r.ok){status.textContent=r.error||'未完成';if(r.verification_kind==='captcha_4399')yy4399Verification(r);return}await yyAutoHostCredential(r);await yyGameAuthPage();yyGameAuthShowCredential(r,r.account)}catch(e){status.textContent=e.message}finally{next.disabled=false}};const cancel=document.createElement('button');cancel.className='btn-s';cancel.textContent='取消待处理任务';cancel.onclick=async()=>{const r=await yyGameAuthAPI('POST',{action:'cancel_guest',id:task.id});if(r.ok)await yyGameAuthRefresh();else status.textContent=r.error};card.append(next,cancel);host.append(card)}
 if(batches.length){const b=document.createElement('button');b.className='btn-s';b.textContent='查看批量任务与逐个命名';b.onclick=()=>window.open('https://auth.youyuanqi.dpdns.org/','_blank','noopener');host.append(b)}
}



async function yyCenterRefresh(){await Promise.all([yyRefreshAccounts(true),yyCenterCloudAccounts()])}

async function yyCopyAccountToken(token){try{await navigator.clipboard.writeText(token);T('令牌已复制','o')}catch(e){yyShowTokenDialog(token);T('请长按令牌框全选复制','i')}}
function yyShowTokenDialog(token){openSubPage('账号令牌','<section class="card"><h3>账号令牌</h3><p class="yy-hint">此令牌允许连接该游戏账号，请妥善保存。</p><textarea id="yy-view-token" readonly rows="4" aria-label="账号令牌"></textarea><div class="yy-actions"><button class="btn" onclick="yyCopyAccountToken(document.getElementById(\'yy-view-token\').value)">复制令牌</button><button class="btn-s" onclick="document.getElementById(\'yy-view-token\').value=\'\';delete subPageCache[\'账号令牌\'];delete _savedFormState[\'账号令牌\'];closeSubPage()">关闭</button></div></section>');document.getElementById('yy-view-token').value=token}
async function yyAccountTokenAction(id,copy){const field=window.yyEditingAccount?.id===id?document.getElementById('yy-ac-token'):null;if(!copy&&field?.type==='text'){field.type='password';return}let token=field?.value||'';if(!token){const r=await yyRootAPI('POST','/api/youyuan/accounts',{action:'token',id:id});if(!r.ok||!r.token){T(r.error||'这个账号尚未保存令牌','e');return}token=r.token}if(copy){await yyCopyAccountToken(token)}else if(field){field.value=token;field.type='text'}else{yyShowTokenDialog(token)}}

async function yyPatrolAPI(id,method,args=[]){const r=await yyRootAPI('POST',yyAccountPath('/api/youyuan/game/call',id),{method:'observerBridge.'+method,args});if(!r.ok)throw Error(r.error);return r.result}
function yyObservationPage(id){window.yyPatrolAccount=id;openSubPage('机器人观察','<section class="card"><h3>顺序轮巡 / 单人跟随</h3><p class="yy-hint">当前账号：'+yyEscape(yyAccountName(id))+'。需要机器人 OP。只有停留在附近时才可能收到视距内动作，轮巡有空档。</p><label>玩家名单（每行一个；留空使用当前在线列表）</label><textarea id="yy-patrol-players" rows="3"></textarea><div class="yy-form-grid"><div><label>多玩家传送间隔（秒）</label><input id="yy-patrol-interval" type="number" step="0.001" value="0.001"></div><div><label>单玩家跟随间隔（秒）</label><input id="yy-patrol-single" type="number" step="0.1" value="2"></div><div><label>本次运行时长（秒；0为持续）</label><input id="yy-patrol-duration" type="number" step="1" value="60"></div></div><p class="yy-hint">更快提交不保证服务器更快传送或更多收包。停止后清理临时分数并请求返回起点。</p><div class="yy-actions"><button class="btn" onclick="yyStartPatrolUI()">开始观察</button><button class="btn-s" onclick="yyStopPatrolUI()">停止并返回</button><button class="btn-s" onclick="yyPatrolStatusUI()">刷新状态</button><button class="btn-s" onclick="closeSubPage()">返回</button></div><div id="yy-patrol-status" class="yy-readout" aria-live="polite"></div></section>');yyPatrolStatusUI()}
async function yyStartPatrolUI(){try{const players=document.getElementById('yy-patrol-players').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);await yyPatrolAPI(yyPatrolAccount,'patrolStart',[{players,interval_seconds:Number(document.getElementById('yy-patrol-interval').value),single_follow_seconds:Number(document.getElementById('yy-patrol-single').value),duration_seconds:Number(document.getElementById('yy-patrol-duration').value),restore_position:true}]);T('观察已启动','o');await yyPatrolStatusUI()}catch(e){T(e.message,'e')}}
async function yyStopPatrolUI(){try{await yyPatrolAPI(yyPatrolAccount,'patrolStop');await yyPatrolStatusUI();T('已停止；清理与返回已请求','o')}catch(e){T(e.message,'e')}}
async function yyPatrolStatusUI(){const el=document.getElementById('yy-patrol-status');if(!el)return;try{const s=await yyPatrolAPI(yyPatrolAccount,'patrolStatus');if(document.getElementById('yy-patrol-status')!==el)return;el.textContent=[s.active?'正在观察':'已停止','传送提交：'+(s.submitted||0)+' · 路线轮数：'+(s.rounds||0),'实际位置更新：'+(s.position_updates||0)+' · 错过调度间隔：'+(s.missed_intervals||0),'事件：'+Object.entries(s.events||{}).map(([k,v])=>k+' '+v).join(' / '),'玩家：'+(s.players||[]).map(r=>r.score+'. '+r.player).join(' → '),s.error?'错误：'+s.error:'','提交数和位置更新数都不是服务端传送完成次数'].filter(Boolean).join('\n')}catch(e){el.textContent=e.message}}

function yyRelogGameAccount(id){window.yyRelogAccountID=id;openSubPage('更新游戏凭据','<section class="card"><h3>重新登录原账号</h3><p class="yy-hint">用于网易凭据过期。游戏身份必须与原账号一致；成功后原令牌、托管账号与插件仍保留。安全验证需要本人完成。</p><label>网易邮箱</label><input id="yy-relog-email" type="email" autocomplete="username"><label>网易密码</label><input id="yy-relog-password" type="password" autocomplete="off"><div class="yy-actions"><button id="yy-relog-submit" class="btn" onclick="yySubmitGameRelog()">更新登录凭据</button><button class="btn-s" onclick="yyCloseGameRelog()">返回</button></div><p id="yy-relog-result" role="status"></p></section>')}
function yyCloseGameRelog(){document.getElementById('yy-relog-password').value='';delete subPageCache['更新游戏凭据'];delete _savedFormState['更新游戏凭据'];closeSubPage()}
async function yySubmitGameRelog(){const b=document.getElementById('yy-relog-submit'),out=document.getElementById('yy-relog-result');b.disabled=true;out.textContent='正在登录原账号…';try{const r=await yyGameAuthAPI('POST',{action:'reauthenticate',id:yyRelogAccountID,email:document.getElementById('yy-relog-email').value.trim(),password:document.getElementById('yy-relog-password').value});if(!r.ok)throw Error(r.error||'更新未完成');document.getElementById('yy-relog-password').value='';yyCloseGameRelog();await yyCenterRefresh();T('凭据已更新，原令牌保持有效；可以重新连接','o')}catch(e){out.textContent=e.message}finally{b.disabled=false}}
